// Clustered passive graph with painted icon frames and meaningful keystone tradeoffs.
const ICONS={fire:0,frost:1,arc:2,cleave:3,arrow:4,vortex:5,attack:6,life:7,spell:8,crit:9,speed:10,guard:11,multi:4,amplify:6,haste:10,area:5,leech:7,root:8,keystone:8};
const clusterCenters=[];
for(let b=0;b<12;b++)for(let group=0;group<3;group++){let a=b*Math.PI/6+(group%2?.12:0),r=[205,402,620][group],cx=800+Math.cos(a)*r,cy=800+Math.sin(a)*r,cr=[36,48,60][group];clusterCenters.push({x:cx,y:cy,r:cr+13,kind:types[b%6]});for(let j=0;j<5;j++){let id=1+b*15+group*5+j,ang=j*Math.PI*2/5+a;NODES[id].x=cx+Math.cos(ang)*cr;NODES[id].y=cy+Math.sin(ang)*cr;let added={id:NODES.length,x:cx+Math.cos(ang+Math.PI/5)*cr,y:cy+Math.sin(ang+Math.PI/5)*cr,kind:types[b%6],name:schools[b]+'・支流 '+(group*5+j+1),value:NODES[id].major?NODES[id].value/3:NODES[id].value,major:false,links:[id,1+b*15+group*5+(j+1)%5]};NODES.push(added);for(let linked of added.links)NODES[linked].links.push(added.id)}}
const KEYSTONES=[
 {name:'血の契り',code:'blood',desc:'スキルのマナ消費をライフで支払う。最大ライフ +15%。回復を慎重に管理する。',icon:7},
 {name:'鋼の心臓',code:'iron',desc:'最大ライフ +25%、移動速度 15%減。',icon:11},
 {name:'硝子の魂',code:'glass',desc:'与えるダメージ 30%増、最大ライフ 20%減。',icon:9},
 {name:'大いなる共鳴',code:'echo',desc:'範囲スキルの半径 30%増、全ジェムスキルのクールダウン 25%増。',icon:5},
 {name:'不滅の灯',code:'ember',desc:'毎秒最大ライフの2%を回復。生命瓶の回復量は半分。',icon:0},
 {name:'静謐の誓い',code:'still',desc:'毎秒マナ回復 +8、移動速度 10%減。',icon:8}
];
for(let i=0;i<6;i++){let a=i*Math.PI/3+Math.PI/12,id=NODES.length,linked=1+i*30+14,k=KEYSTONES[i];NODES.push({id,x:800+Math.cos(a)*730,y:800+Math.sin(a)*730,kind:'keystone',major:true,name:k.name,value:0,links:[linked],key:k});NODES[linked].links.push(id)}
function hasKey(code){return(p?.nodes||[]).some(id=>NODES[id]?.key?.code===code)}
const keyHP=maxhp,keyDamage=damage,keyBuild=skillBuild;
function keyLifeMultiplier(){return(hasKey('blood')?1.15:1)*(hasKey('iron')?1.25:1)*(hasKey('glass')?.8:1)}
function keyDamageMultiplier(){return hasKey('glass')?1.3:1}
maxhp=()=>Math.round(keyHP()*keyLifeMultiplier());damage=()=>Math.round(keyDamage()*keyDamageMultiplier());
skillBuild=type=>{let b=keyBuild(type);if(b&&hasKey('echo')){if(GEM[type].tags.includes('area'))b.radius*=1.3;b.cool*=1.25}return b};
const keyReady=skillReady;skillReady=n=>{if(n!==0&&n!==3&&hasKey('blood')){let b=skillBuild(p.bindings[skillBindingIndex(n)]);return b&&p.hp>b.cost+1}return keyReady(n)};
let bloodCastPayment=null;
const keyPerform=performAction;performAction=action=>{if(action.n!==0&&hasKey('blood')){if(paused||dead||cd[action.n]>0)return;let b=skillBuild(p.bindings[skillBindingIndex(action.n)]);if(!b||p.hp<=b.cost+1)return;let mana=p.mp,previous=bloodCastPayment,payment={mana,extraMana:0};bloodCastPayment=payment;p.mp=1000;try{keyPerform(action);p.hp-=b.cost}finally{p.mp=Math.max(0,mana-payment.extraMana);bloodCastPayment=previous}}else keyPerform(action)};
const keyHeal=heal;heal=()=>{let hp=p?.hp;keyHeal();if(p&&hasKey('ember'))p.hp=hp+(p.hp-hp)*.5};
const keyStat=stat;stat=key=>keyStat(key)+(key==='speed'?(hasKey('iron')?-15:0)+(hasKey('still')?-10:0):key==='regen'&&hasKey('still')?8:0);
const keyUpdate=update;update=dt=>{let active=started&&!paused;keyUpdate(dt);if(active&&!dead&&hasKey('ember'))p.hp=Math.min(maxhp(),p.hp+maxhp()*.02*dt)};
function iconMarkup(type,extra=''){let i=ICONS[type]??8;return '<span class="painted-icon '+extra+'" style="background-position:'+(i%4)*100/3+'% '+Math.floor(i/4)*50+'%"></span>'}
gemIcon=type=>iconMarkup(type,'gem-icon');
let treeQuery='';
function iconSVG(index,x,y,r){return '<svg x="'+(x-r)+'" y="'+(y-r)+'" width="'+r*2+'" height="'+r*2+'" viewBox="'+(index%4*100)+' '+Math.floor(index/4)*100+' 100 100" overflow="hidden" style="pointer-events:none"><image href="assets/ability-atlas.png" width="400" height="300" preserveAspectRatio="none"/></svg>'}
treeHtml=()=>{let owned=new Set(p.nodes),edges=[];NODES.forEach(n=>n.links.forEach(id=>{if(id>n.id)edges.push('<line x1="'+n.x+'" y1="'+n.y+'" x2="'+NODES[id].x+'" y2="'+NODES[id].y+'" class="'+(owned.has(n.id)&&owned.has(id)?'learned':'')+'"/>')}));let decorations=clusterCenters.map(c=>'<circle class="cluster-ring" cx="'+c.x+'" cy="'+c.y+'" r="'+c.r+'"/><circle class="cluster-ring inner" cx="'+c.x+'" cy="'+c.y+'" r="'+(c.r-8)+'"/>'+iconSVG(ICONS[c.kind],c.x,c.y,15)).join('');return '<div class="tree-toolbar"><span>'+NODES.length+' ノード · 残り <b>'+p.points+'</b> pt · 取得 '+(p.nodes.length-1)+'</span><input id="treeSearch" placeholder="生命・攻撃・誓い…" oninput="searchTree(this.value)" aria-label="パッシブを検索"><button onclick="zoomTree(-.15)">−</button><button onclick="zoomTree(.15)">＋</button><button onclick="refundTree()">全返還</button></div><p class="muted">ドラッグで移動・ホイールで拡大縮小。明るい枠は取得可能。大きなノードはKeystone：利点と代償があります。</p><div id="treeViewport"><svg id="tree" width="'+1600*treeZoom+'" height="'+1600*treeZoom+'" viewBox="0 0 1600 1600">'+decorations+edges.join('')+NODES.map(n=>{let radius=n.id===0?23:n.key?21:n.major?15:9,icon=n.key?.icon??ICONS[n.kind]??8;return '<g data-node="'+n.id+'" role="button" tabindex="0" aria-label="'+n.name+'" onclick="inspectNode('+n.id+')" onkeydown="if(event.key===\'Enter\')inspectNode('+n.id+')" class="node '+(n.key?'keystone ':'')+(owned.has(n.id)?'owned':nodeAvailable(n.id)?'available':'locked')+'"><circle cx="'+n.x+'" cy="'+n.y+'" r="'+(radius+3)+'"/>'+iconSVG(icon,n.x,n.y,radius*.76)+'<circle class="rim" cx="'+n.x+'" cy="'+n.y+'" r="'+(radius+5)+'"/><title>'+n.name+' '+(n.key?n.key.desc:(MODS[n.kind]?.[0]||'')+' +'+n.value)+'</title></g>'}).join('')+'</svg></div><div id="nodeDetail"></div>'};
inspectNode=id=>{treeFocus=id;let n=NODES[id];$('nodeDetail').innerHTML=iconMarkup(n.key?'spell':n.kind)+'<div><b>'+n.name+'</b><p>'+(n.key?n.key.desc:(MODS[n.kind]?.[0]||'開始地点')+(n.value?' +'+n.value:''))+'</p></div><button onclick="buyNode('+id+')" '+(!nodeAvailable(id)||!p.points?'disabled':'')+'>'+(p.nodes.includes(id)?'取得済み':'1 pt で取得')+'</button>'};
function searchTree(query){treeQuery=query;document.querySelectorAll('[data-node]').forEach(el=>{let n=NODES[+el.dataset.node],match=query&&(n.name+' '+(MODS[n.kind]?.[0]||'')+' '+(n.key?.desc||'')).includes(query);el.classList.toggle('search-match',!!match)})}
const constellationPanel=panel;panel=kind=>{constellationPanel(kind);if(kind==='skills'&&started&&!dead){let vp=$('treeViewport'),drag=null;vp.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,sx:vp.scrollLeft,sy:vp.scrollTop,moved:false}});vp.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4&&!drag.moved){drag.moved=true;vp.setPointerCapture(e.pointerId)}if(drag.moved){vp.scrollLeft=drag.sx-dx;vp.scrollTop=drag.sy-dy}});vp.addEventListener('pointerup',()=>{setTimeout(()=>drag=null,0)});vp.addEventListener('click',e=>{if(drag?.moved){e.stopPropagation();e.preventDefault()}},true);vp.addEventListener('wheel',e=>{e.preventDefault();zoomTree(e.deltaY<0?.08:-.08)},{passive:false});$('treeSearch').value=treeQuery;searchTree(treeQuery)}};
// Painted action bar icons are actual skill illustrations, not Unicode placeholders.
document.querySelectorAll('.actions button').forEach((b,i)=>{b.insertAdjacentHTML('afterbegin',iconMarkup(['cleave','fire','frost','speed','life'][i],'bar-icon'))});
let lastBindings='';const iconHud=drawHud;drawHud=()=>{iconHud();let signature=p.bindings?.join(',');if(signature!==lastBindings){lastBindings=signature;let buttons=document.querySelectorAll('.actions button');for(let i=0;i<2;i++){let icon=buttons[i+1].querySelector('.bar-icon'),type=p.bindings?.[i],idx=ICONS[type]??8;icon.style.backgroundPosition=(idx%4)*100/3+'% '+Math.floor(idx/4)*50+'%'}}};

